import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// Palette sampled from the print (Hokusai, The Great Wave off Kanagawa)
const PAL = {
  paper: 0xf2ead4, deep: 0x1b4d7a, mid: 0x4e83b4, light: 0xa9c4d9,
  foam: 0xf7f3e6, boat: 0xe3b48a, boatDark: 0x8a5a35,
  fuji: 0xd7dde0, fujiFoot: 0x5b7f95, gray: 0x8b8d85
};

const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('c'), antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));

const scene = new THREE.Scene();
scene.background = new THREE.Color(PAL.paper);
scene.fog = new THREE.Fog(PAL.paper, 180, 380);

const camera = new THREE.PerspectiveCamera(34, innerWidth / innerHeight, 0.1, 500);
const camTarget = new THREE.Vector3(6, 20, 0);
camera.position.set(6, 20, 175);

function onResize() {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
}
addEventListener('resize', onResize);
onResize();

scene.add(new THREE.HemisphereLight(0xfff6df, 0x9fb6c9, 1.15));
const sun = new THREE.DirectionalLight(0xfff1d6, 1.7);
sun.position.set(-40, 60, 80);
scene.add(sun);
const fill = new THREE.DirectionalLight(0xbcd4e8, 0.5);
fill.position.set(60, 20, 40);
scene.add(fill);

